@using sv_4d7b83c6bac84cb983706b6d89e6d328.Services
@inject IJSRuntime JS

<div class="message-list" @ref="_listRef" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }
    @foreach (var message in Messages)
