toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    border-bottom: 1px solid #1e1f22;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    position: relative;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.full-width {
    width: 80%;
}

.chat-main.with-thread {
    width: 55%;
}

::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #dbdee1;
}

::deep .message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #f2f3f5;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #949ba4;
}

/* Message list */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #949ba4;
    font-size: 0.85rem;
}

::deep .message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    margin-bottom: 4px;
    position: relative;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

::deep .message-content {
    margin-top: 4px;
    font-size: 0.9rem;
    line-height: 1.4;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dbdee1;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #3f4147;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
}

::deep .action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
    font-size: 0.9rem;
    transition: background 0.1s;
}

::deep .action-btn:hover {
    background: #3f4147;
}

::deep .emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    z-index: 10;
}

::deep .emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.2rem;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .emoji-option:hover {
    background: #3f4147;
}

/* Message input */
::deep .message-input {
    padding: 12px 16px;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

::deep .message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dbdee1;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-input textarea::placeholder {
    color: #6d6f78;
}

::deep .send-btn {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 10px 16px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
::deep .thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    color: #dbdee1;
    border-left: 1px solid #1e1f22;
    display: flex;
    flex-direction: column;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #949ba4;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .close-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

::deep .thread-reply {
    padding: 8px 0;
    border-bottom: 1px solid #3f414733;
}

